-- Table structure for table `actividades_servicio`
--

DROP TABLE IF EXISTS `actividades_servicio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `actividades_servicio` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `servicio_tecnologico_id` bigint unsigned NOT NULL,
  `descripcion` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha_inicio` date NOT NULL,
  `fecha_finalizacion` date NOT NULL,
  `objetivos` longtext COLLATE utf8mb4_unicode_ci,
