JOSE ZORTO AGUILERA','579',NULL,NULL,'docente',NULL,354,NULL,NULL,NULL,NULL,'2026-07-23 21:59:01','2026-07-23 21:59:01'),(354,'KAREN LORENABAQUEDANO BARAHONA','15166',NULL,NULL,'docente',NULL,355,NULL,NULL,NULL,NULL,'2026-07-28 14:55:59','2026-07-28 14:55:59'),(355,'FRANCISCO ANTONIO  PORTILLO NUNEZ','10453','96853526',NULL,'docente',1,356,42,232,NULL,NULL,'2026-07-29 14:12:38','2026-07-29 14:19:23'),(356,'JIMENA MARIA MEJIA ROMERO','11608','97995162',NULL,'docente',1,357,42,232,NULL,NULL,'2026-07-29 15:52:13','2026-07-29 15:57:26'),(357,'ANYA MABEL ARIAS SOBALVARRO','15778',NULL,NULL,'docente',NULL,358,NULL,NULL,NULL,NULL,'2026-07-29 16:59:07','2026-07-29 16:59:07'),(358,'JEL  CURLP','11841',NULL,NULL,'docente',NULL,359,NULL,NULL,NULL,NULL,'2026-07-31 17:56:11','2026-07-31 17:56:11'),(359,'LAURA VILLARS MORALES','5480',NULL,NULL,'docente',NULL,360,NULL,NULL,NULL,NULL,'2026-07-31 23:11:15','2026-07-31 23:11:15'),(360,'HAZARIA LILYBETHFLORES GIRON','15132',NULL,NULL,'docente',NULL,361,NULL,NULL,NULL,NULL,'2026-07-31 23:57:22','2026-07-31 23:57:22');
