--
-- Table structure for table `empleado_codigos_investigacion`
--

DROP TABLE IF EXISTS `empleado_codigos_investigacion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `empleado_codigos_investigacion` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `empleado_id` bigint unsigned NOT NULL,
  `codigo_proyecto` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre_proyecto` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `rol_docente` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `año` year DEFAULT NULL,
  `estado_verificacion` enum('pendiente','verificado','rechazado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendiente',
  `observaciones_admin` text COLLATE utf8mb4_unicode_ci,
  `verificado_por` bigint unsigned DEFAULT NULL,
  `fecha_verificacion` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `emp_cod_inv_codigo_emp_unique` (`codigo_proyecto`,`empleado_id`),
  KEY `empleado_codigos_investigacion_verificado_por_foreign` (`verificado_por`),
  KEY `emp_cod_inv_emp_estado_idx` (`empleado_id`,`estado_verificacion`),
  CONSTRAINT `empleado_codigos_investigacion_empleado_id_foreign` FOREIGN KEY (`empleado_id`) REFERENCES `empleado` (`id`) ON DELETE CASCADE,
  CONSTRAINT `empleado_codigos_investigacion_verificado_por_foreign` FOREIGN KEY (`verificado_por`) REFERENCES `empleado` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=148 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

